test('vatSummary with single line calculates base and VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 9500 cents * 1 = 9500 gross, 9025 after tier discount
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;
  const result = vatSummary([invoice]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // DEV-HOUR: 9500 * 1 = 9500; with 5% tier discount = 9025
  assert.equal(result[0].base, 9025);
  // VAT = 9025 * 21 / 100 = 1895.25 -> 1895
  assert.equal(result[0].vat, 1895);
});

test('vatSummary accumulates multiple lines with same VAT rate', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 9500, merged, total 19000
      { sku: 'DES-HOUR', qty: 1 }, // 8500, same VAT rate, 21%
    ],
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;
  const result = vatSummary([invoice]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // DEV-HOUR: 9500, DES-HOUR: 8500 = 18000 total; with 5% tier discount = 17100
  assert.equal(result[0].base, 17100);
  // VAT = 17100 * 21 / 100 = 3591
  assert.equal(result[0].vat, 3591);
});

test('vatSummary accumulates multiple invoices with same VAT rate', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 9500, gold tier 5% = 9025
  });

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-12-16',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 9500, standard tier 0% = 9500
  });

  let inv1 = issueInvoice(inv1Result.value, ['INV-2025-0001']).value;
  let inv2 = issueInvoice(inv2Result.value, ['INV-2025-0001', 'INV-2025-0002']).value;

  const result = vatSummary([inv1, inv2]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // 9025 + 9500 = 18525 base
  assert.equal(result[0].base, 18525);
  // VAT = 18525 * 21 / 100 = 3890.25 -> 3890
  assert.equal(result[0].vat, 3890);
});

test('vatSummary sorts by rate descending', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 1 }, // 9% VAT
