  });

  let issued = issueInvoice(issuedResult.value, ['INV-2025-0001']).value;

  const result = vatSummary([draftResult.value, issued]);

  // Only issued invoice should be counted
  assert.equal(result.length, 1);
  // Standard tier (C-002), no discount: 9500 base
  assert.equal(result[0].base, 9500);
