    terms: 'NET14', // Due 2025-12-29
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;
  const fee = lateFee(invoice, '2025-12-29'); // On due date

  assert.equal(fee, 0);
});

test('lateFee returns 0 for invoice with future due date', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14', // Due 2025-12-29
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;
  const fee = lateFee(invoice, '2025-12-20'); // Before due date

  assert.equal(fee, 0);
});

test('lateFee calculates fee for one day overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 95000 total with 5% discount = 90250
    terms: 'NET14', // Due 2025-12-29
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;
  const totals = invoiceTotals(invoice);
  // lateFee = 90250 * 0.0004 * 1 = 36.1 -> 36 cents
  const fee = lateFee(invoice, '2025-12-30'); // 1 day overdue

  assert.equal(fee, 36);
});

test('lateFee calculates fee for multiple days overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14', // Due 2025-12-29
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;
  const totals = invoiceTotals(invoice);
  // lateFee = total * 0.0004 * 7
  const expectedFee = Math.round(totals.total * 0.0004 * 7);
  const fee = lateFee(invoice, '2026-01-05'); // 7 days overdue

  assert.equal(fee, expectedFee);
});

test('lateFee returns 0 for paid invoice', () => {
