  const fee = lateFee(invoiceResult.value, '2026-01-05');

  // Draft invoices don't have a dueDate, should return 0
  assert.equal(fee, 0);
});

test('lateFee increases with more days overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14', // Due 2025-12-29
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;

  const fee1 = lateFee(invoice, '2025-12-30'); // 1 day
  const fee7 = lateFee(invoice, '2026-01-05'); // 7 days
  const fee30 = lateFee(invoice, '2026-01-28'); // 30 days

  assert.ok(fee1 > 0);
  assert.ok(fee7 > fee1);
  assert.ok(fee30 > fee7);
  // Fee should scale linearly with days
  assert.equal(fee7, fee1 * 7);
  assert.equal(fee30, fee1 * 30);
});

test('lateFee with very small balance', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'STICKER', qty: 1 }], // 50 cents
    terms: 'NET14',
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;
  // Due is ~47-50 cents after discount and VAT
  // lateFee = 50 * 0.0004 * 7 = 0.14 -> 0 cents (rounded)
  const fee = lateFee(invoice, '2026-01-05'); // 7 days

  assert.equal(fee, 0);
});

test('lateFee with large invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'BRAND-BOOK', qty: 5 }], // 245000 cents each
    terms: 'NET14',
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;
  // Total: 245000 * 5 = 1225000, with 5% tier discount = 1163750
  // lateFee = 1163750 * 0.0004 * 10 = 4655 cents
  const fee = lateFee(invoice, '2026-01-08'); // 10 days overdue

  assert.ok(fee > 4000);
  assert.ok(fee < 5000);
});

test('lateFee rounds correctly with banker\'s rounding', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 9500 * 0.95 = 9025
    terms: 'NET14',
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;
  // lateFee = 9025 * 0.0004 * 1 = 3.61 -> 4 cents (banker's rounding)
  const fee = lateFee(invoice, '2025-12-30'); // 1 day

  assert.equal(fee, 4);
});

test('lateFee returns 0 if dueDate is undefined (draft invoice)', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const draftInvoice = invoiceResult.value;
  // Draft invoice should not have dueDate set
  const fee = lateFee(draftInvoice, '2026-01-05');

  assert.equal(fee, 0);
});

