    terms: 'NET14',
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;
  const totals = invoiceTotals(invoice);
  invoice = recordPayment(invoice, { amount: totals.total, date: '2025-12-28' }).value;

  const fee = lateFee(invoice, '2026-01-05'); // Well past due date but paid

  assert.equal(fee, 0);
});

test('lateFee calculates fee on remaining balance for partially paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // ~90250 after discount
    terms: 'NET14', // Due 2025-12-29
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;
  invoice = recordPayment(invoice, { amount: 50000, date: '2025-12-28' }).value;

  // Remaining balance: 90250 - 50000 = 40250 (approximately, accounting for VAT)
  // lateFee = remaining_balance * 0.0004 * 7 (7 days overdue)
  const fee = lateFee(invoice, '2026-01-05'); // 7 days overdue

  // 40250 * 0.0004 * 7 = 112.7 -> 113 cents (approximately)
  assert.ok(fee > 0);
});

