test('lateFee increases with more days overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14', // Due 2025-12-29
  });

  let invoice = issueInvoice(invoiceResult.value, []).value;

  const fee1 = lateFee(invoice, '2025-12-30'); // 1 day
  const fee7 = lateFee(invoice, '2026-01-05'); // 7 days
  const fee30 = lateFee(invoice, '2026-01-28'); // 30 days

  assert.ok(fee1 > 0);
  assert.ok(fee7 > fee1);
  assert.ok(fee30 > fee7);
  // Fee should scale linearly with days (accounting for rounding)
  assert.equal(fee7, Math.round(fee1 * 7));
  assert.equal(fee30, Math.round(fee1 * 30));
});

